declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';$notice=flash('reset_notice');$dev=flash('dev_reset_link');$error=flash('reset_error');$pageTitle='Forgot Password';require __DIR__.'/includes/header.php';?><main class="auth-page"><section class="auth-shell"><aside class="auth-aside"><span class="eyebrow"><span class="dot"></span> Account recovery</span><h1>Let's get you<br>back in.</h1><p>Password recovery starts with a time-limited database token. In production, the token link should be sent by email.</p></aside><div class="auth-form"><h2>Forgot password?</h2><p>Enter your account email.</p><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><?php if($dev):?><div class="alert alert-success">Local development reset link: <a href="<?=e($dev)?>">Open reset page</a></div><?php endif;?><form method="post" action="<?=e(url('auth/request-reset.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-group"><label>EMAIL</label><input class="form-control" type="email" name="email" required></div><button class="btn btn-primary btn-block">Request reset</button></form><div class="auth-switch"><a href="login.php">Back to login</a></div></div></section></main><?php require __DIR__.'/includes/footer.php';?>